static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      const DATA_TYPE rr = r[i];

      j = 0;
      for (; j < _PB_M; )
	{
	  size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - j));

	  vfloat32m1_t vs = __riscv_vle32_v_f32m1((const float*)&s[j], vl);
	  vfloat32m1_t vA = __riscv_vle32_v_f32m1((const float*)&A[i][j], vl);
	  vfloat32m1_t vp = __riscv_vle32_v_f32m1((const float*)&p[j], vl);

	  vfloat32m1_t vrr = __riscv_vfmv_v_f_f32m1((float)rr, vl);
	  vfloat32m1_t vmul = __riscv_vfmul_vv_f32m1(vrr, vA, vl);
	  vs = __riscv_vfadd_vv_f32m1(vs, vmul, vl);
	  __riscv_vse32_v_f32m1((float*)&s[j], vs, vl);

	  vfloat32m1_t vmul2 = __riscv_vfmul_vv_f32m1(vA, vp, vl);
	  vfloat32m1_t vq = __riscv_vle32_v_f32m1((const float*)&q[i], vl);
	  vq = __riscv_vfadd_vv_f32m1(vq, vmul2, vl);
	  __riscv_vse32_v_f32m1((float*)&q[i], vq, vl);

	  j += (int)vl;
	}
    }
#pragma endscop

}

