static inline DATA_TYPE my_exp_scalar(DATA_TYPE x) {
    return (DATA_TYPE)exp((double)x);
}

static inline DATA_TYPE my_pow_scalar(DATA_TYPE x, DATA_TYPE y) {
    return (DATA_TYPE)pow((double)x, (double)y);
}

void kernel_deriche(int w, int h, DATA_TYPE alpha,
                    DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
                    DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
                    DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
                    DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    DATA_TYPE k = (DATA_TYPE)(1.0 - my_exp_scalar(-alpha)) *
                  (DATA_TYPE)(1.0 - my_exp_scalar(-alpha)) /
                  (DATA_TYPE)(1.0 + 2.0 * alpha * my_exp_scalar(-alpha) - my_exp_scalar(2.0 * alpha));

    DATA_TYPE a1 = k, a2 = k * my_exp_scalar(-alpha) * (alpha - 1.0),
              a3 = k * my_exp_scalar(-alpha) * (alpha + 1.0),
              a4 = -k * my_exp_scalar(-2.0 * alpha),
              a5 = k, a6 = k, a7 = k, a8 = k;

    DATA_TYPE b1 = my_pow_scalar(2.0, -alpha), b2 = my_exp_scalar(-2.0 * alpha);
    DATA_TYPE c1 = 1.0, c2 = 1.0;

    for (int i = 0; i < w; ++i) {
        DATA_TYPE ym1 = 0.0, ym2 = 0.0, xm1 = 0.0;
        for (int j = 0; j < h; ++j) {
            y1[i][j] = a1 * imgIn[i][j] + a2 * xm1 + b1 * ym1 + b2 * ym2;
            xm1 = imgIn[i][j];
            ym2 = ym1;
            ym1 = y1[i][j];
        }
    }

    for (int i = 0; i < w; ++i) {
        DATA_TYPE yp1 = 0.0, yp2 = 0.0, xp1 = 0.0, xp2 = 0.0;
        for (int j = h - 1; j >= 0; --j) {
            y2[i][j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            xp2 = xp1;
            xp1 = imgIn[i][j];
            yp2 = yp1;
            yp1 = y2[i][j];
        }
    }

    for (int i = 0; i < w; ++i) {
        for (int j = 0; j < h; ++j) {
            imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
        }
    }

    for (int j = 0; j < h; ++j) {
        DATA_TYPE tm1 = 0.0, ym1 = 0.0, ym2 = 0.0;
        for (int i = 0; i < w; ++i) {
            y1[i][j] = a5 * imgOut[i][j] + a6 * tm1 + b1 * ym1 + b2 * ym2;
            tm1 = imgOut[i][j];
            ym2 = ym1;
            ym1 = y1[i][j];
        }
    }

    for (int j = 0; j < h; ++j) {
        DATA_TYPE tp1 = 0.0, tp2 = 0.0, yp1 = 0.0, yp2 = 0.0;
        for (int i = w - 1; i >= 0; --i) {
            y2[i][j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            tp2 = tp1;
            tp1 = imgOut[i][j];
            yp2 = yp1;
            yp1 = y2[i][j];
        }
    }

    for (int i = 0; i < w; ++i) {
        for (int j = 0; j < h; ++j) {
            imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
        }
    }
}

