static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   int i = 0;
   for (; i + 4 <= k; i += 4) {
      sum += r[k-i-1]*y[i];
      sum += r[k-i-2]*y[i+1];
      sum += r[k-i-3]*y[i+2];
      sum += r[k-i-4]*y[i+3];
   }
   for (; i < k; i++) {
      sum += r[k-i-1]*y[i];
   }

   alpha = - (r[k] + sum)/beta;

   int j = 0;
   for (; j + 4 <= k; j += 4) {
      z[j] = y[j] + alpha*y[k-j-1];
      z[j+1] = y[j+1] + alpha*y[k-j];
      z[j+2] = y[j+2] + alpha*y[k-j-1];
      z[j+3] = y[j+3] + alpha*y[k-j];
   }
   for (; j < k; j++) {
      z[j] = y[j] + alpha*y[k-j-1];
   }

   for (j = 0; j < k; j++) {
     y[j] = z[j];
   }
   y[k] = alpha;
 }
#pragma endscop

}

