static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];

      for (i = 1; i < _PB_NX; i++)
	{
	  int j = 0;
	  for (; j < _PB_NY; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NY - j));
	      vfloat32m1_t v_ey = __riscv_vle32_v_f32m1((const float*)&ey[i][j], vl);
	      vfloat32m1_t v_hz = __riscv_vle32_v_f32m1((const float*)&hz[i][j], vl);
	      vfloat32m1_t v_hz_prev = __riscv_vle32_v_f32m1((const float*)&hz[i-1][j], vl);
	      vfloat32m1_t v_diff = __riscv_vfsub_vv_f32m1(v_hz, v_hz_prev, vl);
	      vfloat32m1_t v_coef = __riscv_vfmv_v_f_f32m1(0.5f, vl);
	      vfloat32m1_t v_term = __riscv_vfmul_vv_f32m1(v_coef, v_diff, vl);
	      v_ey = __riscv_vfsub_vv_f32m1(v_ey, v_term, vl);
	      __riscv_vse32_v_f32m1((float*)&ey[i][j], v_ey, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX; i++)
	{
	  int j = 1;
	  for (; j < _PB_NY; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NY - j));
	      vfloat32m1_t v_ex = __riscv_vle32_v_f32m1((const float*)&ex[i][j], vl);
	      vfloat32m1_t v_hz = __riscv_vle32_v_f32m1((const float*)&hz[i][j], vl);
	      vfloat32m1_t v_hz_up = __riscv_vle32_v_f32m1((const float*)&hz[i][j-1], vl);
	      vfloat32m1_t v_diff = __riscv_vfsub_vv_f32m1(v_hz, v_hz_up, vl);
	      vfloat32m1_t v_coef = __riscv_vfmv_v_f_f32m1(0.5f, vl);
	      vfloat32m1_t v_term = __riscv_vfmul_vv_f32m1(v_coef, v_diff, vl);
	      v_ex = __riscv_vfsub_vv_f32m1(v_ex, v_term, vl);
	      __riscv_vse32_v_f32m1((float*)&ex[i][j], v_ex, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX - 1; i++)
	{
	  int j = 0;
	  for (; j < _PB_NY - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)((_PB_NY - 1) - j));
	      vfloat32m1_t v_hz = __riscv_vle32_v_f32m1((const float*)&hz[i][j], vl);
	      vfloat32m1_t v_ex_down = __riscv_vle32_v_f32m1((const float*)&ex[i][j+1], vl);
	      vfloat32m1_t v_ex_up = __riscv_vle32_v_f32m1((const float*)&ex[i][j], vl);
	      vfloat32m1_t v_ey_down = __riscv_vle32_v_f32m1((const float*)&ey[i+1][j], vl);
	      vfloat32m1_t v_ey_up = __riscv_vle32_v_f32m1((const float*)&ey[i][j], vl);
	      vfloat32m1_t v_sum1 = __riscv_vfsub_vv_f32m1(v_ex_down, v_ex_up, vl);
	      vfloat32m1_t v_sum2 = __riscv_vfsub_vv_f32m1(v_ey_down, v_ey_up, vl);
	      vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(v_sum1, v_sum2, vl);
	      vfloat32m1_t v_coef = __riscv_vfmv_v_f_f32m1(0.7f, vl);
	      vfloat32m1_t v_term = __riscv_vfmul_vv_f32m1(v_coef, v_sum, vl);
	      v_hz = __riscv_vfsub_vv_f32m1(v_hz, v_term, vl);
	      __riscv_vse32_v_f32m1((float*)&hz[i][j], v_hz, vl);
	      j += (int)vl;
	    }
	}
    }

#pragma endscop
}

