static
void kernel_floyd_warshall(int n,
                           DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
  {
    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE* row_i = path[i];
      DATA_TYPE* row_k = path[k];
      DATA_TYPE path_ik = row_i[k];

      int j = 0;
      while (j < _PB_N)
      {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));

        vint32m1_t v_ij = __riscv_vle32_v_i32m1((const int32_t*)(row_i + j), vl);
        vint32m1_t v_kj = __riscv_vle32_v_i32m1((const int32_t*)(row_k + j), vl);
        vint32m1_t v_ik = __riscv_vmv_v_x_i32m1((int32_t)path_ik, vl);
        vint32m1_t v_sum = __riscv_vadd_vv_i32m1(v_ik, v_kj, vl);
        vint32m1_t v_res = __riscv_vmin_vv_i32m1(v_ij, v_sum, vl);

        __riscv_vse32_v_i32m1((int32_t*)(row_i + j), v_res, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop

}

