static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *__restrict cptr = C[i];
    const DATA_TYPE *__restrict aptr = A[i];

    for (j = 0; j < _PB_NJ; j++)
      cptr[j] *= beta;

    for (k = 0; k < _PB_NK; k++) {
      const DATA_TYPE aik = aptr[k];
      const DATA_TYPE *__restrict bptr = B[k];

      int j = 0;
      while (j < _PB_NJ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));

        vfloat32m1_t vc = __riscv_vle32_v_f32m1((const float *)(cptr + j), vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)(bptr + j), vl);
        vfloat32m1_t va = __riscv_vfmv_v_f_f32m1((float)aik, vl);
        vfloat32m1_t vp = __riscv_vfmul_vv_f32m1(va, vb, vl);
        vc = __riscv_vfadd_vv_f32m1(vc, vp, vl);
        __riscv_vse32_v_f32m1((float *)(cptr + j), vc, vl);

        j += (int)vl;
      }
    }
  }
#pragma endscop

}

