static
void kernel_gramschmidt(int m, int n,
                        DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                        DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
                        DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE nrm = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
      {
        int idx = 0;
        while (idx < _PB_M)
          {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
            vfloat32m1_t v = __riscv_vle32_v_f32m1((const float*)&A[idx][k], vl);
            vfloat32m1_t w = __riscv_vfmul_vv_f32m1(v, v, vl);
            float tmp[64];
            __riscv_vse32_v_f32m1(tmp, w, vl);
            for (size_t t = 0; t < vl; ++t) nrm += tmp[t];
            idx += (int)vl;
          }
      }
#else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
#endif

      R[k][k] = SQRT_FUN(nrm);

#if defined(__riscv_vector)
      {
        int idx = 0;
        while (idx < _PB_M)
          {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
            vfloat32m1_t vq = __riscv_vle32_v_f32m1((const float*)&A[idx][k], vl);
            vfloat32m1_t vr = __riscv_vfmv_v_f_f32m1((float)R[k][k], vl);
            vfloat32m1_t q = __riscv_vfdiv_vv_f32m1(vq, vr, vl);
            __riscv_vse32_v_f32m1((float*)&Q[idx][k], q, vl);
            idx += (int)vl;
          }
      }
#else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
#endif

      for (j = k + 1; j < _PB_N; j++)
        {
          DATA_TYPE r = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
          {
            int idx = 0;
            while (idx < _PB_M)
              {
                size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
                vfloat32m1_t vq = __riscv_vle32_v_f32m1((const float*)&Q[idx][k], vl);
                vfloat32m1_t va = __riscv_vle32_v_f32m1((const float*)&A[idx][j], vl);
                vfloat32m1_t t = __riscv_vfmul_vv_f32m1(vq, va, vl);
                float tmp[64];
                __riscv_vse32_v_f32m1(tmp, t, vl);
                for (size_t t = 0; t < vl; ++t) r += tmp[t];
                idx += (int)vl;
              }
          }
#else
          for (i = 0; i < _PB_M; i++)
            r += Q[i][k] * A[i][j];
#endif

          R[k][j] = r;

#if defined(__riscv_vector)
          {
            int idx = 0;
            while (idx < _PB_M)
              {
                size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - idx));
                vfloat32m1_t vq = __riscv_vle32_v_f32m1((const float*)&Q[idx][k], vl);
                vfloat32m1_t vr = __riscv_vfmv_v_f_f32m1((float)r, vl);
                vfloat32m1_t vb = __riscv_vfsub_vv_f32m1(__riscv_vle32_v_f32m1((const float*)&A[idx][j], vl),
                                                          __riscv_vfmul_vv_f32m1(vq, vr, vl), vl);
                __riscv_vse32_v_f32m1((float*)&A[idx][j], vb, vl);
                idx += (int)vl;
              }
          }
#else
          for (i = 0; i < _PB_M; i++)
            A[i][j] = A[i][j] - Q[i][k] * r;
#endif
        }
    }
#pragma endscop

}

