static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;
  const DATA_TYPE c0125 = SCALAR_VAL(0.125);
  const DATA_TYPE c2 = SCALAR_VAL(2.0);

#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   c0125 * (A[i+1][j][k] - c2 * A[i][j][k] + A[i-1][j][k])
                                 + c0125 * (A[i][j+1][k] - c2 * A[i][j][k] + A[i][j-1][k])
                                 + c0125 * (A[i][j][k+1] - c2 * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
            }
        }
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   c0125 * (B[i+1][j][k] - c2 * B[i][j][k] + B[i-1][j][k])
                                + c0125 * (B[i][j+1][k] - c2 * B[i][j][k] + B[i][j-1][k])
                                + c0125 * (B[i][j][k+1] - c2 * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
           }
       }
    }
#pragma endscop

}

