static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;
  const size_t nn = (size_t)n;
  const size_t nm1 = nn - 1;

  for (t = 0; t < tsteps; ++t)
  {
    size_t idx = 1;
    while (idx < nn)
    {
      size_t vl = __riscv_vsetvl_e32m8(nm1 - idx + 1);

      vfloat32m8_t a0 = __riscv_vle32_v_f32m8((const float*)&A[idx - 1], vl);
      vfloat32m8_t a1 = __riscv_vle32_v_f32m8((const float*)&A[idx], vl);
      vfloat32m8_t a2 = __riscv_vle32_v_f32m8((const float*)&A[idx + 1], vl);

      vfloat32m8_t sum = __riscv_vfadd_vv_f32m8(a0, a1, vl);
      sum = __riscv_vfadd_vv_f32m8(sum, a2, vl);
      vfloat32m8_t res = __riscv_vfmul_vf_f32m8(sum, 0.33333f, vl);

      __riscv_vse32_v_f32m8((float*)&B[idx], res, vl);

      idx += vl;
    }

    idx = 1;
    while (idx < nn)
    {
      size_t vl = __riscv_vsetvl_e32m8(nm1 - idx + 1);

      vfloat32m8_t b0 = __riscv_vle32_v_f32m8((const float*)&B[idx - 1], vl);
      vfloat32m8_t b1 = __riscv_vle32_v_f32m8((const float*)&B[idx], vl);
      vfloat32m8_t b2 = __riscv_vle32_v_f32m8((const float*)&B[idx + 1], vl);

      vfloat32m8_t sum = __riscv_vfadd_vv_f32m8(b0, b1, vl);
      sum = __riscv_vfadd_vv_f32m8(sum, b2, vl);
      vfloat32m8_t res = __riscv_vfmul_vf_f32m8(sum, 0.33333f, vl);

      __riscv_vse32_v_f32m8((float*)&A[idx], res, vl);

      idx += vl;
    }
  }
}

