static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  const DATA_TYPE coeff = SCALAR_VAL(0.2);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
	{
	  int j = 1;
	  for (; j < _PB_N - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - 1 - j));

	      vfloat32m1_t a0 = __riscv_vle32_v_f32m1((const float*)&A[i][j], vl);
	      vfloat32m1_t a1 = __riscv_vle32_v_f32m1((const float*)&A[i][j-1], vl);
	      vfloat32m1_t a2 = __riscv_vle32_v_f32m1((const float*)&A[i][j+1], vl);
	      vfloat32m1_t a3 = __riscv_vle32_v_f32m1((const float*)&A[i+1][j], vl);
	      vfloat32m1_t a4 = __riscv_vle32_v_f32m1((const float*)&A[i-1][j], vl);

	      vfloat32m1_t sum = __riscv_vfadd_vv_f32m1(a0, a1, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, a2, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, a3, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, a4, vl);

	      vfloat32m1_t res = __riscv_vfmul_vf_f32m1(sum, coeff, vl);
	      __riscv_vse32_v_f32m1((float*)&B[i][j], res, vl);

	      j += (int)vl;
	    }
	}

      for (i = 1; i < _PB_N - 1; i++)
	{
	  int j = 1;
	  for (; j < _PB_N - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - 1 - j));

	      vfloat32m1_t b0 = __riscv_vle32_v_f32m1((const float*)&B[i][j], vl);
	      vfloat32m1_t b1 = __riscv_vle32_v_f32m1((const float*)&B[i][j-1], vl);
	      vfloat32m1_t b2 = __riscv_vle32_v_f32m1((const float*)&B[i][j+1], vl);
	      vfloat32m1_t b3 = __riscv_vle32_v_f32m1((const float*)&B[i+1][j], vl);
	      vfloat32m1_t b4 = __riscv_vle32_v_f32m1((const float*)&B[i-1][j], vl);

	      vfloat32m1_t sum = __riscv_vfadd_vv_f32m1(b0, b1, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, b2, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, b3, vl);
	      sum = __riscv_vfadd_vv_f32m1(sum, b4, vl);

	      vfloat32m1_t res = __riscv_vfmul_vf_f32m1(sum, coeff, vl);
	      __riscv_vse32_v_f32m1((float*)&A[i][j], res, vl);

	      j += (int)vl;
	    }
	}
    }
#pragma endscop

}

