static inline DATA_TYPE max_score(DATA_TYPE a, DATA_TYPE b) {
    return a > b ? a : b;
}

static inline DATA_TYPE match(base a, base b) {
    return (DATA_TYPE)0;
}

static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
                     DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
    for (int i = _PB_N - 1; i >= 0; --i) {
        for (int j = i + 1; j < _PB_N; ++j) {
            DATA_TYPE best = table[i][j];

            if (j - 1 >= 0) {
                best = max_score(best, table[i][j - 1]);
            }
            if (i + 1 < _PB_N) {
                best = max_score(best, table[i + 1][j]);
            }

            if (j - 1 >= 0 && i + 1 < _PB_N) {
                if (i < j - 1) {
                    best = max_score(best, table[i + 1][j - 1] + match(seq[i], seq[j]));
                } else {
                    best = max_score(best, table[i + 1][j - 1]);
                }
            }

            int k = i + 1;
            for (; k + 7 < j; k += 8) {
                DATA_TYPE t0 = table[i][k] + table[k + 1][j];
                DATA_TYPE t1 = table[i][k + 1] + table[k + 2][j];
                DATA_TYPE t2 = table[i][k + 2] + table[k + 3][j];
                DATA_TYPE t3 = table[i][k + 3] + table[k + 4][j];
                DATA_TYPE t4 = table[i][k + 4] + table[k + 5][j];
                DATA_TYPE t5 = table[i][k + 5] + table[k + 6][j];
                DATA_TYPE t6 = table[i][k + 6] + table[k + 7][j];
                DATA_TYPE t7 = table[i][k + 7] + table[k + 8][j];

                best = max_score(best, t0);
                best = max_score(best, t1);
                best = max_score(best, t2);
                best = max_score(best, t3);
                best = max_score(best, t4);
                best = max_score(best, t5);
                best = max_score(best, t6);
                best = max_score(best, t7);
            }
            for (; k < j; ++k) {
                best = max_score(best, table[i][k] + table[k + 1][j]);
            }

            table[i][j] = best;
        }
    }
}

#include <riscv_vector.h>

static
void kernel_seidel_2d(int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++)
    for (i = 1; i <= _PB_N - 2; i++)
      for (j = 1; j <= _PB_N - 2; j++)
        A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
                   + A[i][j-1] + A[i][j] + A[i][j+1]
                   + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1])/SCALAR_VAL(9.0);
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    const DATA_TYPE *__restrict__ Ai = A[i];
    const DATA_TYPE *__restrict__ Bi = B[i];
    DATA_TYPE *__restrict__ Ci = C[i];

    for (j = 0; j < _PB_N; j++)
    {
      temp2 = 0;
      DATA_TYPE cij = Ci[j];

      int kk = 0;
      for (; kk + 3 < i; kk += 4)
      {
        cij += alpha * Bi[j] * Ai[kk];
        temp2 += B[kk][j] * Ai[kk];

        cij += alpha * Bi[j] * Ai[kk + 1];
        temp2 += B[kk + 1][j] * Ai[kk + 1];

        cij += alpha * Bi[j] * Ai[kk + 2];
        temp2 += B[kk + 2][j] * Ai[kk + 2];

        cij += alpha * Bi[j] * Ai[kk + 3];
        temp2 += B[kk + 3][j] * Ai[kk + 3];
      }
      for (; kk < i; kk++)
      {
        cij += alpha * Bi[j] * Ai[kk];
        temp2 += B[kk][j] * Ai[kk];
      }

      Ci[j] = beta * cij + alpha * Bi[j] * Ai[i] + alpha * temp2;
    }
  }
#pragma endscop
}

#include <riscv_vector.h>

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik = A[i][k];
      DATA_TYPE bik = B[i][k];

      int j = 0;
      for (; j + 3 <= i; j += 4) {
        C[i][j]     += aik * alpha * B[j][k]     + bik * alpha * A[j][k];
        C[i][j + 1] += aik * alpha * B[j + 1][k] + bik * alpha * A[j + 1][k];
        C[i][j + 2] += aik * alpha * B[j + 2][k] + bik * alpha * A[j + 2][k];
        C[i][j + 3] += aik * alpha * B[j + 3][k] + bik * alpha * A[j + 3][k];
      }
      for (; j <= i; j++) {
        C[i][j] += aik * alpha * B[j][k] + bik * alpha * A[j][k];
      }
    }
  }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik = A[i][k];
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * aik * A[j][k];
    }
  }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_trisolv(int n,
                    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
                    DATA_TYPE POLYBENCH_1D(x,N,n),
                    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    x[i] = b[i];
    for (j = 0; j < i; j++)
    {
      x[i] -= L[i][j] * x[j];
    }
    x[i] = x[i] / L[i][i];
  }
#pragma endscop

}

#include <riscv_vector.h>

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE sum = 0.0;
      for (k = i + 1; k < _PB_M; k++)
      {
        sum += A[k][i] * B[k][j];
      }
      B[i][j] = alpha * sum;
    }
  }
#pragma endscop

}
